struct DSU {
    int n;
    vector<int> p;
    vector<long long> sz;
    DSU(int n=0): n(n), p(n+1), sz(n+1,1) {
        for(int i=1;i<=n;i++) p[i]=i;
    }
    int find(int x){ return p[x]==x?x:p[x]=find(p[x]); }

    bool unite(int a,int b, long long &sa, long long &sb) {
        a = find(a); b = find(b);
        if(a==b) return false;
        if(sz[a] < sz[b]) swap(a,b);

        sa = sz[a];
        sb = sz[b];
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    if(!(cin>>n)) return 0;
    vector<int> w(n+1);
    for(int i=1;i<=n;i++) cin>>w[i];
    vector<vector<int>> adj(n+1);
    for(int k=0;k<n-1;k++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> ord(n);
    for(int i=0;i<n;i++) ord[i]=i+1;
    sort(ord.begin(), ord.end(), [&](int a,int b){
        return w[a] < w[b];
    });

    DSU dsu_max(n);
    vector<char> active(n+1, 0);
    long long sum_max = 0;
    for(int u : ord){
        active[u] = 1;
        for(int v : adj[u]){
            if(!active[v]) continue;
            long long sa=0, sb=0;
            if(dsu_max.unite(u, v, sa, sb)){
                sum_max += (long long)w[u] * (sa * sb);
            }
        }
    }

    sort(ord.begin(), ord.end(), [&](int a,int b){
        return w[a] > w[b];
    });
    DSU dsu_min(n);
    fill(active.begin(), active.end(), 0);
    long long sum_min = 0;
    for(int u : ord){
        active[u] = 1;
        for(int v : adj[u]){
            if(!active[v]) continue;
            long long sa=0, sb=0;
            if(dsu_min.unite(u, v, sa, sb)){
                sum_min += (long long)w[u] * (sa * sb);
            }
        }
    }

    long long T = (sum_max - sum_min);
    cout << T << '\n';
}